{"file_text": "using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Pancakes", Category = "Breakfast", Ingredients = "2 cups flour\n2 eggs\n1.5 cups milk\n2 tbsp sugar\n1 tsp baking powder\nPinch of salt", Steps = "1. Mix dry ingredients in a bowl.\n2. Whisk eggs and milk together.\n3. Combine wet and dry ingredients until just mixed.\n4. Heat a non-stick pan over medium heat.\n5. Pour 1/4 cup batter per pancake.\n6. Flip when bubbles form on surface.\n7. Cook until golden brown on both sides." },
        new Recipe { Id = 2, Title = "Scrambled Eggs", Category = "Breakfast", Ingredients = "4 eggs\n2 tbsp butter\n2 tbsp milk\nSalt and pepper", Steps = "1. Crack eggs into a bowl, add milk, salt, and pepper.\n2. Whisk until well combined.\n3. Melt butter in a pan over medium-low heat.\n4. Pour in egg mixture.\n5. Gently stir with a spatula as eggs set.\n6. Remove from heat when still slightly wet.\n7. Serve immediately." },
        new Recipe { Id = 3, Title = "Spaghetti Carbonara", Category = "Dinner", Ingredients = "400g spaghetti\n200g pancetta\n4 egg yolks\n100g Pecorino Romano\n2 cloves garlic\nBlack pepper", Steps = "1. Cook spaghetti in salted boiling water until al dente.\n2. Fry pancetta until crispy.\n3. Mix egg yolks with grated Pecorino and black pepper.\n4. Drain pasta, reserving 1 cup pasta water.\n5. Toss hot pasta with pancetta (off heat).\n6. Add egg mixture and toss quickly.\n7. Add pasta water as needed for creamy consistency." },
        new Recipe { Id = 4, Title = "Grilled Chicken Salad", Category = "Lunch", Ingredients = "2 chicken breasts\nMixed greens\nCherry tomatoes\nCucumber\nRed onion\nOlive oil\nLemon juice\nSalt and pepper", Steps = "1. Season chicken breasts with salt, pepper, and olive oil.\n2. Grill chicken for 6-7 minutes per side.\n3. Let chicken rest 5 minutes, then slice.\n4. Toss greens, tomatoes, cucumber, and onion.\n5. Arrange sliced chicken on top.\n6. Drizzle with olive oil and lemon juice.\n7. Season to taste." },
        new Recipe { Id = 5, Title = "Chocolate Chip Cookies", Category = "Desserts", Ingredients = "2.25 cups flour\n1 cup butter (softened)\n0.75 cup sugar\n0.75 cup brown sugar\n2 eggs\n1 tsp vanilla\n1 tsp baking soda\n2 cups chocolate chips", Steps = "1. Preheat oven to 375°F (190°C).\n2. Cream butter and sugars until fluffy.\n3. Beat in eggs and vanilla.\n4. Mix in flour and baking soda.\n5. Fold in chocolate chips.\n6. Drop rounded tablespoons onto baking sheet.\n7. Bake 9-11 minutes until golden edges.\n8. Cool on pan for 2 minutes, then transfer to rack." },
        new Recipe { Id = 6, Title = "Tomato Basil Soup", Category = "Lunch", Ingredients = "6 large tomatoes\n1 onion\n3 cloves garlic\nFresh basil leaves\n2 cups vegetable broth\n2 tbsp olive oil\nSalt and pepper\n0.5 cup heavy cream", Steps = "1. Halve tomatoes, toss with olive oil, roast at 400°F for 25 min.\n2. Sauté diced onion and garlic until soft.\n3. Add roasted tomatoes and broth.\n4. Simmer for 15 minutes.\n5. Blend until smooth.\n6. Stir in cream and torn basil.\n7. Season with salt and pepper." },
        new Recipe { Id = 7, Title = "Beef Tacos", Category = "Dinner", Ingredients = "1 lb ground beef\nTaco seasoning\n8 taco shells\nShredded lettuce\nDiced tomatoes\nShredded cheese\nSour cream\nSalsa", Steps = "1. Brown ground beef in a skillet over medium-high heat.\n2. Drain excess fat.\n3. Add taco seasoning and water per package directions.\n4. Simmer 5 minutes until thickened.\n5. Warm taco shells in oven.\n6. Fill shells with seasoned beef.\n7. Top with lettuce, tomatoes, cheese, sour cream, and salsa." },
        new Recipe { Id = 8, Title = "Tiramisu", Category = "Desserts", Ingredients = "6 egg yolks\n0.75 cup sugar\n1.25 cups mascarpone\n2 cups heavy cream\n2 cups strong espresso (cooled)\n3 tbsp coffee liqueur\n24 ladyfinger cookies\nCocoa powder", Steps = "1. Whisk egg yolks and sugar until thick and pale.\n2. Add mascarpone and mix until smooth.\n3. Whip heavy cream to stiff peaks, fold into mascarpone mixture.\n4. Combine espresso and liqueur in a shallow dish.\n5. Quickly dip ladyfingers in coffee mixture.\n6. Layer dipped ladyfingers in a dish, spread cream on top.\n7. Repeat layers. Refrigerate 4+ hours.\n8. Dust with cocoa powder before serving." },
    };

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            recipe.TotalRating += stars;
            recipe.RatingCount++;
        }
    }
}
", "path": "/tmp/sv-99a9c7e21f7a47eb85dbc51669be8f7a/RecipeShare/Services/RecipeService.cs"}

